        return `<article class="list-item"><div class="list-item-head"><div><h3>${ctx.esc(project.name)}</h3><p>${ctx.fmtNumber(project.units)} وحدة · ${project.mode==='sale'?'للبيع':'للتأجير'} · ${ctx.esc(levelLabel(project.priceLevel))}</p></div><span class="tag ${project.status==='مكتمل'?'positive':''}">${ctx.esc(project.status)}${project.status==='قيد الإنشاء'?` ${progress}%`:''}</span></div>${project.mode==='sale'?metrics([['مباعة',ctx.fmtNumber(project.sold)],['على المخطط',ctx.fmtNumber(project.presold)],['متبقية',ctx.fmtNumber(Math.max(0,project.units-project.sold-project.presold))],['إيراد المبيعات',ctx.fmtMoney(project.salesRevenue)]]):metrics([['مؤجرة',ctx.fmtNumber(project.leased)],['الإشغال',pctOf(project.units?project.leased/project.units:0)],['إيجار اليوم',ctx.fmtMoney(project.today?.rent||0)],['الإيجار التراكمي',ctx.fmtMoney(project.rentRevenue)]])}<div class="company-transfer-form"><label>مستوى ${project.mode==='sale'?'السعر':'الإيجار'}<select id="rePrice-${ctx.esc(project.id)}">${core.PRICE_LEVELS.map(level=>`<option value="${level}" ${Number(level)===Number(project.priceLevel)?'selected':''}>${ctx.esc(levelLabel(level))}</option>`).join('')}</select></label></div><div class="action-row">${action('realestate-set-price','اعتماد السعر',`data-project="${ctx.esc(project.id)}"`,true)}</div>${acceleration?`<div class="action-row">${action('realestate-accelerate-construction',`تسريع الإنشاء · ${ctx.fmtMoney(acceleration.fee)}`,`data-project="${ctx.esc(project.id)}" data-fee="${acceleration.fee}" data-complete-day="${acceleration.completeDay}" data-days-saved="${acceleration.daysSaved}"`,true)}<span class="section-mini">اختصار المدة المتبقية للنصف · توفير مخطط ${acceleration.daysSaved} يومًا · مرة واحدة</span></div>`:project.constructionAcceleration?(Number(project.constructionAcceleration.completeDay)===Number(project.constructionAcceleration.day)?'<p class="section-mini">تسريع مدفوع ومعتمد · سُلِّم المشروع فور صرف الشيك.</p>':'<p class="section-mini">تسريع مدفوع ومعتمد · تستمر دفعات البناء عبر الإقفال اليومي.</p>'):''}${project.status==='قيد الإنشاء'&&!project.constructionLoanId?`<div class="action-row">${(core.CONSTRUCTION_SHARES||[]).map(share=>action('realestate-finance-construction',`تمويل إنشاء ${share*100}% · ${ctx.fmtMoney(Math.round((Number(project.landCost)+Number(project.buildCost))*share))}`,`data-project="${ctx.esc(project.id)}" data-share="${share}"`,true)).join('')}</div>`:project.constructionLoanId?`<p class="section-mini">ممول بقرض إنشاء ${ctx.fmtMoney(project.constructionLoan)} · ${ctx.esc(project.constructionLoanId)}</p>`:''}${core.canSellToFund?.(project)?`<div class="action-row">${action('realestate-sell-to-fund',`بيع المبنى لصندوق · ${ctx.fmtMoney(core.fundValue(project,ctx.state))}`,`data-project="${ctx.esc(project.id)}"`,true)}</div>`:''}${internalLeases.length?`${sectionTitle('عقود المجموعة الداخلية')}${leaseRows}`:''}${leaseForm}</article>`;
