  // Build 375: the compact page parts (madar-shell.css .pv-*).
  // A choice made on a facility desk returns to that desk (data-return-facility), else to the company page.
  function refreshFromView(ctx,btn,panel,arg){const facility=btn?.dataset?.returnFacility;return facility?refreshView(ctx,'facilityManage',{id:facility,tab:'operations'}):refreshView(ctx,panel,arg);}
  function pvHero(ctx,label,big,unit='',chips=[],bar=null){return `<div class="pv-hero"><small>${ctx.esc(label)}</small><div class="pv-big"><b>${ctx.esc(big)}</b>${unit?`<em>${ctx.esc(unit)}</em>`:''}</div>${bar===null||!Number.isFinite(Number(bar))?'':`<div class="pv-bar"><i style="width:${Math.max(0,Math.min(100,Number(bar))).toFixed(1)}%"></i></div>`}${chips.filter(Boolean).length?`<div class="pv-sub">${chips.filter(Boolean).map(chip=>`<span class="pv-chip">${ctx.esc(chip)}</span>`).join('')}</div>`:''}</div>`;}
  function pvFacts(items){return `<div class="pv-facts">${items.map(([label,value,cls=''])=>`<div class="pv-fact"><span>${text(label)}</span><b class="${safeToken(cls)}">${text(value)}</b></div>`).join('')}</div>`;}
  function pvRow(ctx,badge,title,sub,value='',valueSub=''){return `<div class="pv-row"><div class="pv-badge">${ctx.esc(badge)}</div><div class="pv-name"><b>${ctx.esc(title)}</b>${sub?`<span>${ctx.esc(sub)}</span>`:''}</div>${value||valueSub?`<div class="pv-val">${value?`<b>${ctx.esc(value)}</b>`:''}${valueSub?`<span class="muted">${ctx.esc(valueSub)}</span>`:''}</div>`:''}</div>`;}
  // Three ready choices; the current one is marked and disabled.
  function pvOptions(id,label,values,current,valueLabel,attrs){return `<div class="pv-optrow">${label?`<span>${text(label)}</span>`:''}<div class="pv-opt">${values.map(value=>action(id,valueLabel(value),`${attrs(value)}${String(value)===String(current)?' disabled data-current="1" data-disabled-reason="هذا هو الاختيار الحالي."':''}`,true)).join('')}</div></div>`;}
  // Money: what the facility cost and costs, and its closure (a facility with stationed assets cannot close).
  function facilityMoney(f,m,stationed,ctx,extraFacts=[]){
    const hq=['hq','office'].includes(f.kind),settlement=(m?.staff||0)*1000+(Number(f.dailyCost)||0)*30;
    return `${pvFacts([['استثمار التأسيس',ctx.fmtMoney(f.cost||0)],['التكلفة اليومية',ctx.fmtMoney(Number(f.dailyCost)||0)],...extraFacts].slice(0,6))}<p class="pv-note">تُخصم التكلفة اليومية في الإقفال المالي للشركة المالكة، ورواتب الفريق في مسير الرواتب.</p>${hq?'':stationed===null?'<p class="pv-note">جارٍ تحديث ملخص الأسطول من العامل.</p>':stationed>0?'<p class="pv-note">لا تُغلق منشأة فيها أصول متمركزة؛ انقلها أو بعها أولًا.</p>':`<div class="pv-btns">${action('facility-close',`إغلاق المنشأة · تسوية ${ctx.fmtMoney(settlement)}`,`data-id="${f.id}"`,true).replace('<button ','<button data-wide="1" ')}</div>`}`;
  }
  // Build 375: a telecom branch's own desk (the airport-shaped page showed "operating gates"): its subscribers by plan,
