  const OFFICIAL_NEWS_SOURCES=Object.freeze({contracts:'العقود والعملاء',finance:'الإدارة المالية','business-world':'العلاقات التجارية',corporate:'إدارة المجموعة',facilities:'إدارة المنشآت',procurement:'إدارة المشتريات',hr:'الموارد البشرية',energy:'شركة الطاقة',banking:'البنك',realestate:'العقارات',governance:'حوكمة المجموعة',market:'إدارة الاستثمارات',mobility:'شركة التنقل','customer-companies':'خدمة العملاء والمبيعات'});
  const NEWS_LIST_LIMIT=80,NEWS_PAGE_SIZE=25;
