    if(!Object.prototype.hasOwnProperty.call(OFFICIAL_NEWS_KINDS,kind)||!event?.id||!reference||!String(event.title||'').trim()||!Number.isFinite(Number(event.at)))return false;
    if(event.official!==true||!String(event.sourceDomain||'').trim()||!String(event.sourceRef||'').trim()||!String(event.documentRef||'').trim())return false;
