      rows.push({...event,type:'official',category:OFFICIAL_NEWS_KINDS[event.kind],text:event.title,official:true,sourceLabel:OFFICIAL_NEWS_KINDS[event.kind],sourceRef:event.sourceRef||event.reference,documentRef:event.documentRef||event.reference});
