    const statusMap={healthy:['سليم','positive'],warning:['تحذيرات',''],critical:['حالة حرجة','negative']},status=statusMap[report.status]||statusMap.warning;
    const issues=(report.issues||[]).slice(0,60),diag=ctx.state.diagnostics||{},resolved=(diag.resolvedIssues||[]).slice(0,20),recent=(diag.events||[]).slice(0,30),integrity=ctx.businessIntegrity?.()||{status:'warning',counts:{critical:0,warning:0,total:0},byDomain:{}},closure=ctx.deliveryClosure?.()||{},ledger=ctx.businessLedger?.()||{},workflow=globalThis.GH_WORKFLOW?.summary?.(ctx.state)||{count:0,lastIntegrity:null};
    const recorder=ctx.faultRecorder?.()||null,recorderActive=!!recorder?.active,recorderSummary=recorder?.summary||null,recorderEvents=(recorder?.events||[]).slice(0,8),recorderFindings=recorderSummary?.findings||[],frameSummary=recorder?.frameSummary||recorderSummary?.frameSummary||{};
    const faultLabels={FRAME_DROP:'تأخر إطار مرئي',LONG_TASK_TRACE:'مهمة طويلة على المسار الرئيسي',CALENDAR_ADVANCE_FAILED:'فشل تقديم التاريخ',SIM_PROGRESS_STALLED:'توقف تقدم زمن المحاكاة',ASSET_REVENUE_PROGRESS_STALLED:'تقدم الوقت دون حركة/إيراد',LIVE_BACKLOG_CLAMP:'قصّ backlog المتراكم',LIVE_SPEED_UNDERRUN:'السرعة الفعلية أقل من المطلوبة',SIM_SLICE_CANCELLED:'إلغاء شريحة محاكاة',SIM_STAGE_HARD_TASK:'مرحلة محاكاة ثقيلة'};
    const sevLabel={critical:'حرج',warning:'تحذير',info:'معلومة'};
