  async function signedDomainCommand(ctx,domain,name,payload={},options={}){if(typeof ctx?.runAuthorizedDomainCommand!=='function')throw new Error('خدمة التفويض والحفظ الدائم غير متاحة');const context={...(options.context||{})};if(options.subjectId!=null)context.subjectId=String(options.subjectId);const request={domain,name,payload,silent:options.silent!==false,...(Object.keys(context).length?{context}:{})};if(options.idempotencyKey)request.idempotencyKey=options.idempotencyKey;if(options.transactionId)request.transactionId=options.transactionId;if(options.afterCommit)request.afterCommit=options.afterCommit;if(typeof options.successNotice==='function')request.successNotice=options.successNotice;const wrapped=await ctx.runAuthorizedDomainCommand(request);if(!wrapped?.ok||!Object.prototype.hasOwnProperty.call(wrapped,'result'))throw new Error('فشل اعتماد الأمر أو حفظه الدائم');return wrapped.result;}

  async function confirmDecision(ctx,message,risk='normal',action='company-decision'){
    if(typeof globalThis.GH_INTERFACE?.confirm==='function')return globalThis.GH_INTERFACE.confirm(String(message||''),{title:'مراجعة القرار',accept:'تأكيد',state:ctx.state,panel:ctx.currentPanel,action,risk});
    notify(ctx,'تعذر فتح نافذة التأكيد. لم يُنفذ الإجراء.','error');return false;
  }
