    const insuranceSelections=[...rootNode.querySelectorAll('[data-insurance-risk-select]')],insuranceBatchButtons=[...rootNode.querySelectorAll('[data-gh-action="insurance-decide-risks-batch"]')],insuranceSelectionCount=rootNode.querySelector('#insBatchSelectedCount'),insuranceMaximum=Number(globalThis.GH_INSURANCE_CORE?.MAX_OPEN_RISKS)||5;const updateInsuranceBatchSelection=()=>{const selected=insuranceSelections.filter(input=>input.checked);if(insuranceSelectionCount)insuranceSelectionCount.textContent=`${selected.length} / ${insuranceMaximum}`;for(const button of insuranceBatchButtons)button.disabled=selected.length===0;};for(const input of insuranceSelections){if(input.dataset.batchSelectionBound==='1')continue;input.dataset.batchSelectionBound='1';input.addEventListener('change',()=>{if(input.checked&&insuranceSelections.filter(row=>row.checked).length>insuranceMaximum){input.checked=false;notify(ctx,`يمكن تحديد ${insuranceMaximum} مخاطر كحد أقصى.`);}updateInsuranceBatchSelection();});}updateInsuranceBatchSelection();
    const requestSelections=[...rootNode.querySelectorAll('[data-realestate-request-select]')],batchButtons=[...rootNode.querySelectorAll('[data-gh-action="realestate-decide-requests-batch"]')],selectionCount=rootNode.querySelector('#reBatchSelectedCount');const updateRealEstateBatchSelection=()=>{const selected=requestSelections.filter(input=>input.checked);if(selectionCount)selectionCount.textContent=`${selected.length} / 5`;for(const button of batchButtons)button.disabled=selected.length===0;};for(const input of requestSelections){if(input.dataset.batchSelectionBound==='1')continue;input.dataset.batchSelectionBound='1';input.addEventListener('change',()=>{if(input.checked&&requestSelections.filter(row=>row.checked).length>5){input.checked=false;notify(ctx,'يمكن تحديد خمسة طلبات كحد أقصى.');}updateRealEstateBatchSelection();});}updateRealEstateBatchSelection();
    rootNode.querySelectorAll('[data-facility-tab]').forEach(btn=>btn.addEventListener('click',()=>ctx.openDrawer('facilityManage',{id:ctx.currentArg?.id||ctx.currentArg,tab:btn.dataset.facilityTab})));
