    rootNode.querySelectorAll('[data-bank-tab]').forEach(btn=>btn.addEventListener('click',()=>ctx.openDrawer('bank',{tab:btn.dataset.bankTab})));
    rootNode.querySelectorAll('[data-insurance-tab]').forEach(btn=>btn.addEventListener('click',()=>ctx.openDrawer('insurance',{tab:btn.dataset.insuranceTab})));
    rootNode.querySelectorAll('[data-realestate-tab]').forEach(btn=>btn.addEventListener('click',()=>ctx.openDrawer('realestate',{tab:btn.dataset.realestateTab})));
